<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Bars\{BarsLesson,ProviderResult};use StudPulse\Database\DB;use StudPulse\Http\ApiError;use StudPulse\Security\{Auth,Crypto};use StudPulse\Integrations\{MpeiSchedule,ScheduleSubgroups};final class LessonLibrary{public static function mark(Auth$auth,ProviderResult$schedule):ProviderResult{$m=self::scope($auth);if(!$m||MpeiSchedule::groupKey($schedule->details['group']??'')!==MpeiSchedule::groupKey($m['canonical_code'])){return$schedule;}$tracks=ScheduleSubgroups::lessonTracks($schedule);$expires=time()+86400;$items=[];foreach($schedule->items as$lesson){if(!ScheduleSubgroups::hasTeacher($lesson['teacher_name']??''))$lesson['teacher_name']='';$label=trim($lesson['subgroup_name']??'');if(preg_match('/^(?:0|[-—–]|все|вся группа)$/uiD',$label)){$label='';}$track=$tracks[$lesson['id']]??null;if($lesson['status']!=='cancelled'){$data=[$m['group_id'],$m['term_id'],$lesson['subject_title'],$lesson['class_type'],$lesson['start_at'],$lesson['end_at'],$label,$expires,$track];$payload=rtrim(strtr(base64_encode(json_encode($data,JSON_THROW_ON_ERROR)),'+/','-_'),'=');$lesson['libraryRef']=$payload.'.'.Crypto::hash('lesson-library:'.$payload);}$items[]=$lesson;}return new ProviderResult($items,$schedule->source,$schedule->observedAt,$schedule->fixture,$schedule->details);}public static function scope(Auth$auth):?array{if($auth->membership)return$auth->membership;$group=LibraryGroup::selected($auth->user['id']);if(!$group)return null;$scope=LibraryGroup::scope($group);return$scope['term_id']?[...$scope,'canonical_code'=>$scope['code']]:null;}public static function resolve(Auth$auth,string$reference,bool$create=false):array{$m=self::scope($auth)??throw new ApiError(403,'GROUP_UNVERIFIED','Группа расписания не найдена в каталоге StudPulse');if(preg_match('/^[a-f0-9-]{36}$/iD',$reference)){$meeting=Access::meeting($auth,Input::id($reference),$m);if($create&&$meeting['status']==='cancelled'){throw new ApiError(422,'LESSON_CANCELLED','Занятие отменено');}$subject=DB::one('SELECT id,title FROM subjects WHERE id=? AND group_id=? AND term_id=?',[$meeting['subject_id'],$m['group_id'],$m['term_id']])??throw new ApiError(404,'NOT_FOUND','Предмет не найден');return['id'=>$meeting['id'],'subject_id'=>$subject['id'],'subject_title'=>$subject['title'],'start_at'=>$meeting['start_at']];}$parts=explode('.',$reference,2);if(count($parts)!==2||strlen($reference)>3000||!hash_equals(Crypto::hash('lesson-library:'.$parts[0]),$parts[1])){throw new ApiError(404,'LESSON_REFERENCE','Обновите расписание и выберите занятие снова');}$data=json_decode(base64_decode(strtr($parts[0],'-_','+/'),true),true,8,JSON_THROW_ON_ERROR);[$group,$term,$title,$type,$start,$end,$label,$expires]=$data;$track=$data[8]??null;if($group!==$m['group_id']||$term!==$m['term_id']||$expires<time()){throw new ApiError(404,'LESSON_REFERENCE','Занятие недоступно в текущей группе или семестре');}$date=(new \DateTimeImmutable($start,new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('Y-m-d');if(!DB::one('SELECT id FROM terms WHERE id=? AND ? BETWEEN begins_at AND ends_at',[$term,$date])){throw new ApiError(404,'LESSON_REFERENCE','Занятие вне текущего семестра');}$subgroup=null;if($track&&!LibraryTracks::canUse($auth->user['id'],$m['canonical_code'],$track)){throw new ApiError(403,'LESSON_SUBGROUP','Эта пара относится к другой подгруппе');}if(!$track&&$label!==''){$names=ctype_digit($label)?[$label,'Подгруппа '.$label]:[$label,$label];$matches=DB::all('SELECT s.id FROM student_subgroups s JOIN subgroup_memberships sm ON sm.subgroup_id=s.id WHERE s.group_id=? AND s.term_id=? AND s.name IN (?,?) AND sm.user_id=? LIMIT 2',[$group,$term,...$names,$auth->user['id']]);if(count($matches)!==1){throw new ApiError(403,'LESSON_SUBGROUP','Для материалов этой пары нужно подтверждённое членство в подгруппе');}$subgroup=$matches[0]['id'];}$key=BarsLesson::subjectKey($title);$subjects=DB::all('SELECT id,title FROM subjects WHERE group_id=? AND term_id=? AND archived_at IS NULL',[$group,$term]);$matches=array_values(array_filter($subjects,static fn($s)=>BarsLesson::subjectKey($s['title'])===$key));if(count($matches)>1){throw new ApiError(409,'LESSON_SUBJECT','В каталоге найдено несколько подходящих предметов');}$external=hash('sha256',json_encode([$key,BarsLesson::titleKey($type),$start,$end,$track['variant']??$subgroup],JSON_THROW_ON_ERROR));$meeting=DB::one("SELECT id,subject_id FROM class_meetings WHERE provider='ruz' AND group_id=? AND term_id=? AND provider_external_id=?",[$group,$term,$external]);if(!$meeting&&$create){$subject=$matches[0]['id']??null;if($subject===null){$subjectKey=hash('sha256',$key);DB::run("INSERT INTO subjects(id,group_id,term_id,provider,external_id,title) VALUES(?,?,?,'ruz',?,?) ON DUPLICATE KEY UPDATE id=id",[DB::id(),$group,$term,$subjectKey,mb_substr($title,0,180)]);$subject=DB::one("SELECT id FROM subjects WHERE group_id=? AND term_id=? AND provider='ruz' AND external_id=? AND archived_at IS NULL",[$group,$term,$subjectKey])['id']??null;if(!$subject){throw new ApiError(409,'LESSON_SUBJECT','Предмет находится в архиве');}}DB::run("INSERT INTO class_meetings(id,provider,provider_external_id,group_id,term_id,subject_id,subgroup_id,start_at,end_at,class_type,source,last_synced_at) VALUES(?,'ruz',?,?,?,?,?,?,?,?,'ruz',UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE id=id",[DB::id(),$external,$group,$term,$subject,$subgroup,$start,$end,mb_substr($type,0,40)]);$meeting=DB::one("SELECT id,subject_id FROM class_meetings WHERE provider='ruz' AND group_id=? AND term_id=? AND provider_external_id=?",[$group,$term,$external]);}return['id'=>$meeting['id']??null,'subject_id'=>$meeting['subject_id']??($matches[0]['id']??null),'subject_title'=>$matches[0]['title']??$title,'start_at'=>$start,'track'=>$track];}}